(7688917, 1259806, 124190, '<td valign="top">Hysterical! CEMETRY. Take a deep breath.......a beautiful symmetrical cacophony of silence. If there were any more subtle examples of symbolism in this photo it would burst into flames.</td>', 'Hysterical! CEMETRY. Take a deep breath.......a beautiful symmetrical cacophony of silence. If there were any more subtle examples of symbolism in this photo it would burst into flames.', '2021-03-08 08:34:00.000000', NULL, 1),
(7688918, 1259646, 124190, '<td valign="top">Reflection is what first presented to me in this photo.</td>', 'Reflection is what first presented to me in this photo.', '2021-03-08 08:38:44.000000', NULL, 1),
(7688919, 1259610, 124190, '<td valign="top">An arch is by nature is symmetric. The moulding (brace?) extending across the top breaks the symmetry.</td>', 'An arch is by nature is symmetric. The moulding (brace?) extending across the top breaks the symmetry.', '2021-03-08 08:41:09.000000', NULL, 1),
(7688921, 1259805, 124190, '<td valign="top">"Symmetry:the quality of being made up of exactly similar parts facing each other or around an axis."<br/> <br/>Again, the challenge is symmetry. If this,<br/>was reflection, I would score higher.</td>', '"Symmetry:the quality of being made up of exactly similar parts facing each other or around an axis." Again, the challenge is symmetry. If this,was reflection, I would score higher.', '2021-03-08 08:46:31.000000', NULL, 1),
